public ListNode sortList(ListNode head) {
    int n = 0;
    for (ListNode c = head; c != null; c = c.next) n++;
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    for (int size = 1; size < n; size *= 2) {
        ListNode prev = dummy, cur = dummy.next;
        while (cur != null) {
            ListNode left = cur;
            ListNode right = split(left, size);
            cur = split(right, size);       // start of next block
            prev = mergeInto(prev, left, right);
        }
    }
    return dummy.next;
}

// detach first `size` nodes from `node`, return head of the remainder
private ListNode split(ListNode node, int size) {
    for (int i = 1; node != null && i < size; i++) node = node.next;
    if (node == null) return null;
    ListNode rest = node.next;
    node.next = null;
    return rest;
}

// merge a and b, link after prev, return new tail
private ListNode mergeInto(ListNode prev, ListNode a, ListNode b) {
    ListNode tail = prev;
    while (a != null && b != null) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }
        else { tail.next = b; b = b.next; }
        tail = tail.next;
    }
    tail.next = (a != null) ? a : b;
    while (tail.next != null) tail = tail.next;
    return tail;
}

import java.util.ArrayDeque;
import java.util.Deque;

class Node {
    int val;
    Node prev;
    Node next;
    Node child;
}

public Node flatten(Node head) {
    if (head == null) return null;
    Deque<Node> stack = new ArrayDeque<>();
    Node cur = head;
    while (cur != null) {
        if (cur.child != null) {
            if (cur.next != null) stack.push(cur.next);
            cur.next = cur.child;
            cur.child.prev = cur;
            cur.child = null;
        }
        if (cur.next == null && !stack.isEmpty()) {
            Node resume = stack.pop();
            cur.next = resume;
            resume.prev = cur;
        }
        cur = cur.next;
    }
    return head;
}

