public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
    ListNode before = list1;
    for (int i = 0; i < a - 1; i++) before = before.next;  // node at index a-1
    ListNode after = before;
    for (int i = a - 1; i <= b; i++) after = after.next;   // node at index b+1

    before.next = list2;
    ListNode tail = list2;
    while (tail.next != null) tail = tail.next;
    tail.next = after;
    return list1;
}
